    {
      "path": "/home/charl/Moriarty/deliverables/modern-defi-taxonomy-2026-09-08/CATEGORIES.md",
      "sha256": "5bd0ef5cf8e6816b3cf11d86ec0daf54f8e3af682943d303500f7cccf60d1f87"
    }
  ],
  "blinded": false,
  "blinding_note": "README illustrative matrix contains cases resembling prompts; independent application of published rules, not blinded experiment. No expected-label file or benchmark inspected.",
  "agreement_statistic": null,
  "cases": [
    {
      "case": 1,
      "function_labels": [
        "FIN-MON.1",
        "FIN-CRE.2"
      ],
      "object_scope": "issuance/debt module",
      "rationale": "New monetary units and borrower principal/fee debt; separate token from debt position.",
      "ambiguities": []
    },
    {
      "case": 2,
      "function_labels": [
        "FIN-MGT.1"
      ],
      "object_scope": "allocator component",
      "rationale": "Underlying isolated lending market components use FIN-CRE.1.",
      "ambiguities": [
        "CAP.1 applies to subscription/minting component under literal broad rule; tie-break needed."
      ]
    },
    {
      "case": 3,
      "function_labels": [
        "FIN-CRE.1"
      ],
      "object_scope": "bilateral inventory-funded loan instance",
      "rationale": "Maturity/collateral/no early liquidation are facets, not a new function.",
      "ambiguities": [
        "Maturity default and collateral settlement mechanism unspecified."
      ]
    },
    {
      "case": 4,
      "function_labels": [],
      "object_scope": "subscription gateway, fund and manager separately",
      "rationale": "FIN-MGT.2 conditional on actual portfolio mandate; FIN-CAP.1 conditional on new-right issuance.",
      "ambiguities": [
        "Description does not establish portfolio-control authority or whether underlying fund shares are newly issued.",
        "Async/multiasset/external share topology does not prove an ERC implementation."
      ]
    },
    {
      "case": 5,
      "function_labels": [
        "FIN-EXC.2"
      ],
      "object_scope": "solver trade-fulfillment component",
      "rationale": "Origin escrow component separately FIN-MON.3; reimbursement claim has settlement credit risk.",
      "ambiguities": [
        "CRE.1 broad receivable inclusion lacks explicit exclusion for trade pre-funding."
      ]
    },
    {
      "case": 6,
      "function_labels": [],
      "object_scope": "governance incentive/locking component",
      "rationale": "Supporting capability; reward source is inflationary subsidy; no security duty.",
      "ambiguities": [
        "No explicit no-financial-function outcome in rules.",
        "FIN-MON.2 may describe separately scoped payment service but not automatically every incidental reward transfer."
      ]
    }
  ],
  "findings": [
    {
      "id": "CLARITY-01",
      "severity": "medium",
      "issue": "CAP.1 broad new-right subscription definition needs consistent application to ordinary vault shares and external funds."
    },
    {
      "id": "CLARITY-02",
      "severity": "medium",
      "issue": "CRE.1 broad receivable definition overlaps solver trade-settlement pre-funding; explicit financing-obligation tie-break needed."
    },
    {
      "id": "CLARITY-03",
      "severity": "low",
      "issue": "CRE.1 CDP redirect wording also uses can imply inventory lending without inventory funding."
    },
    {
      "id": "CLARITY-04",
      "severity": "medium",
      "issue": "Supporting capability/no-financial-function outcome and incidental payout boundary should be explicit."
    },
    {
      "id": "CLARITY-05",
      "severity": "low",
      "issue": "Subscription-gateway role does not itself establish portfolio mandate."
    }
  ],
  "full_artifact_approval": false
}

